pub fn first(input: &[i64]) -> i64 {
    let mut total = 0;
    let mut count = 0;
    let mut largest = i64::MIN;
    let mut smallest = i64::MAX;
    for value in input {
        total += value;
        count += 1;
        if *value > largest {
            largest = *value;
        }
        if *value < smallest {
            smallest = *value;
        }
    }
    if count == 0 {
        return 0;
    }
    total / count + largest - smallest
}

